    45	sub lock {
    46	    my ($self, $recording, $nonblocking) = @_;
    47	    my $name = $recording ? 'whisper-record-toggle.recording' : 'whisper-record-toggle.lock';
    48	    my $path = $self->_path($name);
    49	    if (-e $path || -l $path) {
    50	        -f $path && !-l $path or _fatal("runtime lock is unsafe: $path");
    51	        (lstat $path)[4] == $< or _fatal("runtime lock ownership is unsafe: $path");
    52	    }
    53	    sysopen my $fh, $path, O_CREAT | O_NOFOLLOW | O_RDWR, 0600
    54	        or _fatal("cannot open runtime lock: $!");
    55	    fcntl($fh, F_SETFD, $recording ? 0 : FD_CLOEXEC)
    56	        or _fatal("cannot configure runtime lock: $!");
    57	    my $mode = LOCK_EX | ($nonblocking ? LOCK_NB : 0);
    58	    if (!flock($fh, $mode)) {
    59	        return undef if $nonblocking && ($!{EAGAIN} || $!{EWOULDBLOCK});
    60	        _fatal("cannot lock runtime state: $!");
    61	    }
    62	    return $fh;
