    16	    my ($message) = @_;
    17	    die "whisper-record-toggle: $message\n";
    18	}
    19	
    20	sub _run {
    21	    my ($self, @arguments) = @_;
    22	    my $systemctl = '/usr/bin/systemctl';
    23	    -x $systemctl && -f $systemctl or _fatal('systemctl is unavailable');
    24	    return system { $systemctl } $systemctl, '--user', @arguments;
    25	}
    26	
    27	sub _detail {
    28	    my ($status) = @_;
    29	    return "exec error: $!" if $status == -1;
    30	    return 'terminated by signal ' . ($status & 127) if $status & 127;
    31	    return 'exit status ' . ($status >> 8);
    32	}
    33	
    34	sub is_active { my ($self, $service) = @_; return $self->_run('--quiet', 'is-active', $service) == 0; }
    35	sub is_failed { my ($self, $service) = @_; return $self->_run('--quiet', 'is-failed', $service) == 0; }
    36	
    37	sub start_recording {
    38	    my ($self) = @_;
    39	    $self->_run('reset-failed', $self->record_service());
    40	    my $status = $self->_run('start', $self->record_service());
    41	    return if $status == 0 && $self->wait_active($self->record_service(), 50);
    42	    _fatal('cannot start recording service: ' . _detail($status));
    43	}
    44	
    45	sub stop_recording {
    46	    my ($self) = @_;
    47	    return if !$self->is_active($self->record_service());
    48	    my $status = $self->_run('stop', $self->record_service());
    49	    $status == 0 or _fatal('cannot stop recording service: ' . _detail($status));
    50	    $self->wait_inactive($self->record_service(), 150)
    51	        or _fatal('recording service did not stop within 15 seconds');
    52	}
    53	
    54	sub start_transcription {
    55	    my ($self) = @_;
    56	    my $status = $self->_run('--no-block', 'start', $self->transcribe_service());
    57	    $status == 0 or _fatal('cannot start transcription service: ' . _detail($status));
    58	}
    59	
    60	sub wait_active {
    61	    my ($self, $service, $attempts) = @_;
    62	    for (1 .. $attempts) {
    63	        return 1 if $self->is_active($service);
    64	        return 0 if $self->is_failed($service);
    65	        sleep 0.1;
    66	    }
    67	    return 0;
    68	}
    69	
    70	sub wait_inactive {
    71	    my ($self, $service, $attempts) = @_;
    72	    for (1 .. $attempts) {
    73	        return 1 if !$self->is_active($service);
    74	        sleep 0.1;
    75	    }
    76	    return 0;
    77	}
